using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace MoreSpace {
static class ChartFileRules {
 static bool Inside(string path,string root){return !String.IsNullOrEmpty(root)&&(String.Equals(path,root,StringComparison.OrdinalIgnoreCase)||Engine.Under(path,root));}
 public static void Validate(Entry entry,string folder){string path=Path.GetFullPath(entry.Path);if(!String.Equals(Path.GetDirectoryName(path).TrimEnd('\\'),Path.GetFullPath(folder).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new IOException("Arquivo fora da pasta revisada.");
  foreach(var root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Windows),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\')})if(Inside(path,root))throw new IOException("Local protegido. Use a desinstalação do aplicativo ou as ferramentas do Windows.");
  if(!Engine.NoLinks(path))throw new IOException("Links não podem ser excluídos aqui.");var f=new FileInfo(path);if(!f.Exists||f.Length!=entry.Size||f.LastWriteTimeUtc!=entry.Modified)throw new IOException("Arquivo alterado desde a leitura. Atualize a lista.");if((f.Attributes&(FileAttributes.System|FileAttributes.ReadOnly|FileAttributes.ReparsePoint))!=0)throw new IOException("Arquivo protegido, somente leitura ou link.");
 }
 public static List<Entry> Read(string folder){if(!Engine.NoLinks(folder))throw new IOException("Pastas com links não são percorridas.");var entries=new List<Entry>();foreach(var f in new DirectoryInfo(folder).EnumerateFiles())try{if((f.Attributes&FileAttributes.ReparsePoint)==0)entries.Add(new Entry{Path=f.FullName,Size=f.Length,Modified=f.LastWriteTimeUtc});}catch(IOException){}catch(UnauthorizedAccessException){}return entries.OrderByDescending(e=>e.Size).ToList();}
}
partial class MainWindow {
 ContextMenuStrip chartMenu;ToolStripItem chartExplore;SpaceItem chartMenuTarget;
 void SetupChartActions(){
  // A dropdown still performs native handle/owner work after Closed. Keep it
  // alive for the form's lifetime instead of disposing from that event.
  chartMenu=new ContextMenuStrip();chartMenu.Items.Add("Ver arquivos / excluir…",null,async delegate{var target=chartMenuTarget;if(target!=null)await ReviewChartFiles(target.Path);});chartExplore=chartMenu.Items.Add("Entrar na pasta",null,async delegate{var target=chartMenuTarget;if(target!=null)await Explore(target.Path);});Disposed+=delegate{chartMenu.Dispose();};
  pie.ContextPick=(sector,point)=>ShowChartMenu(sector==null?null:sector.Item,pie,point);distribution.MouseUp+=delegate(object sender,MouseEventArgs e){if(e.Button!=MouseButtons.Right)return;var row=distribution.GetItemAt(e.X,e.Y);ShowChartMenu(row==null?null:row.Tag as SpaceItem,distribution,e.Location);};
 }
 void ShowChartMenu(SpaceItem item,Control owner,Point point){if(busy||demoMode||currentFolder==null||item==null)return;OpenChartMenu(item,owner,point);}
 void OpenChartMenu(SpaceItem item,Control owner,Point point){if(IsDisposed||Disposing||owner.IsDisposed||chartMenu.IsDisposed)return;chartMenuTarget=item;chartExplore.Visible=item.Directory;chartMenu.Show(owner,point);}
 internal bool ChartMenuDisposed{get{return chartMenu.IsDisposed;}}
 internal int CheckChartMenu(){tabs.SelectedIndex=0;var directory=new SpaceItem{Path=@"C:\Demo",Directory=true};var files=new SpaceItem{Path=@"C:\Demo\Files",Directory=false};for(int i=0;i<30;i++){var target=i%2==0?directory:files;OpenChartMenu(target,i%2==0?(Control)pie:distribution,new Point(12,12));Application.DoEvents();if(chartMenu.IsDisposed||chartMenuTarget!=target||chartExplore.Available!=target.Directory)return 111;chartMenu.Close(ToolStripDropDownCloseReason.AppClicked);Application.DoEvents();if(chartMenu.IsDisposed)return 112;}
  OpenChartMenu(directory,pie,new Point(12,12));OpenChartMenu(files,distribution,new Point(14,14));Application.DoEvents();if(chartMenuTarget!=files||chartMenu.IsDisposed)return 113;chartMenu.Items[0].PerformClick();chartMenu.Close();Application.DoEvents();OpenChartMenu(directory,pie,new Point(12,12));chartExplore.PerformClick();chartMenu.Close();Application.DoEvents();return chartMenu.IsDisposed?114:0;
 }
 async Task ReviewChartFiles(string folder){if(busy||demoMode)return;Busy(true);cancel.Enabled=false;status.Text="Carregando arquivos de "+folder+"…";
  try{var entries=await Task.Run(()=>ChartFileRules.Read(folder));using(var dialog=new ChartFileDialog(folder,entries)){if(dialog.ShowDialog(this)!=DialogResult.OK){status.Text="Nenhum arquivo excluído.";return;}var selected=dialog.Selection;var before=SavingsStore.Snapshot();int count=0;long bytes=0;var messages=new List<string>();status.Text="Excluindo arquivos selecionados…";
   await Task.Run(()=>{foreach(var entry in selected)try{ChartFileRules.Validate(entry,folder);File.Delete(entry.Path);count++;bytes+=entry.Size;messages.Add("EXCLUÍDO PELA HOME "+Engine.Bytes(entry.Size)+" | "+entry.Path);}catch(Exception ex){messages.Add("PRESERVADO "+entry.Path+" | "+ex.Message);}});
   foreach(var message in messages)Log(message);if(count>0)RecordSavings("Arquivos da Home",count,bytes,before);status.Text=count+" arquivos excluídos • "+Engine.Bytes(bytes)+" lógicos • "+(selected.Count-count)+" preservados/falhas.";MessageBox.Show(this,status.Text+"\r\n\r\nConsulte Atividade para detalhes. O gráfico da partição será atualizado; para detalhar pastas novamente, use Explorar pastas.","Resultado");
  }}catch(Exception ex){status.Text="Não foi possível ler a pasta.";MessageBox.Show(this,ex.Message,"Arquivos da pasta");}finally{Busy(false);RefreshOverview();LoadVolumes();}
 }
}
class ChartFileDialog:Form {
 readonly ListView files=new SmoothListView();readonly Label total=new Label();readonly Button remove;bool queued;
 public List<Entry> Selection{get{return files.CheckedItems.Cast<ListViewItem>().Select(i=>(Entry)i.Tag).ToList();}}
 public ChartFileDialog(string folder,List<Entry> entries,bool preselect=false){Text="Arquivos da pasta • +Espaço";Size=new Size(1000,600);MinimumSize=new Size(800,500);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.White;
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=4,ColumnCount=1,Padding=new Padding(18)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));Controls.Add(layout);
  layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text=(folder??"Arquivos grandes selecionados")+"\r\nRevise os arquivos marcados; subpastas não serão apagadas.\r\nExclusão permanente, sem Lixeira. Locais do sistema e arquivos alterados são preservados."},0,0);
  var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};var all=new RoundedButton{Text="Selecionar visíveis",Width=175,Height=36};var clear=new RoundedButton{Text="Desmarcar",Width=120,Height=36};all.Click+=delegate{foreach(ListViewItem row in files.Items)if(row.ForeColor!=Color.Gray)row.Checked=true;};clear.Click+=delegate{foreach(ListViewItem row in files.Items)row.Checked=false;};actions.Controls.Add(all);actions.Controls.Add(clear);total.AutoSize=true;total.Margin=new Padding(16,10,0,0);actions.Controls.Add(total);layout.Controls.Add(actions,0,1);
  files.Dock=DockStyle.Fill;files.View=View.Details;files.FullRowSelect=true;files.CheckBoxes=true;files.ShowItemToolTips=true;files.Columns.Add("Arquivo",220);files.Columns.Add("Tamanho",100);files.Columns.Add("Caminho completo",520);foreach(var e in entries){var row=new ListViewItem(new[]{Path.GetFileName(e.Path),Engine.Bytes(e.Size),e.Path});row.Tag=e;try{ChartFileRules.Validate(e,folder??Path.GetDirectoryName(e.Path));row.Checked=preselect;}catch(Exception ex){row.ForeColor=Color.Gray;row.ToolTipText=ex.Message;}files.Items.Add(row);}layout.Controls.Add(files,0,2);
  var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var cancel=new RoundedButton{Text="Fechar",Width=110,Height=36,DialogResult=DialogResult.Cancel};remove=new RoundedButton{Text="Excluir selecionados…",Width=205,Height=36,Enabled=false};footer.Controls.Add(cancel);footer.Controls.Add(remove);layout.Controls.Add(footer,0,3);CancelButton=cancel;AcceptButton=cancel;
  files.ItemCheck+=delegate(object sender,ItemCheckEventArgs e){if(files.Items[e.Index].ForeColor==Color.Gray){e.NewValue=e.CurrentValue;return;}if(!queued){queued=true;BeginInvoke((Action)(()=>{queued=false;UpdateTotal();}));}};
  remove.Click+=delegate{var chosen=Selection;if(chosen.Count==0)return;using(var confirm=new Form{Text="Confirmar exclusão permanente",Size=new Size(780,480),StartPosition=FormStartPosition.CenterParent,Font=Font}){var panel=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(18)};panel.RowStyles.Add(new RowStyle(SizeType.Absolute,64));panel.RowStyles.Add(new RowStyle(SizeType.Percent,100));panel.RowStyles.Add(new RowStyle(SizeType.Absolute,44));confirm.Controls.Add(panel);panel.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Excluir permanentemente "+chosen.Count+" arquivos ("+Engine.Bytes(chosen.Sum(e=>e.Size))+")?\r\nNão serão enviados à Lixeira. Revise todos os caminhos abaixo."},0,0);panel.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Text=String.Join("\r\n",chosen.Select(e=>e.Path))},0,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var no=new RoundedButton{Text="Cancelar",Width=110,Height=36,DialogResult=DialogResult.Cancel};var yes=new RoundedButton{Text="Excluir definitivamente",Width=210,Height=36,DialogResult=DialogResult.OK};buttons.Controls.Add(no);buttons.Controls.Add(yes);panel.Controls.Add(buttons,0,2);confirm.AcceptButton=no;confirm.CancelButton=no;if(confirm.ShowDialog(this)==DialogResult.OK){DialogResult=DialogResult.OK;Close();}}};UpdateTotal();
 }
 void UpdateTotal(){var selected=Selection;total.Text=selected.Count+" selecionados • "+Engine.Bytes(selected.Sum(e=>e.Size));remove.Enabled=selected.Count>0;}
}
static class ChartFileChecks {
 public static int Run(){string root=Path.Combine(Path.GetTempPath(),"MoreSpace-Chart-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"one.txt"),"test");Directory.CreateDirectory(Path.Combine(root,"nested"));File.WriteAllText(Path.Combine(root,"nested","two.txt"),"test");var list=ChartFileRules.Read(root);if(list.Count!=1)return 81;ChartFileRules.Validate(list[0],root);bool blocked=false;try{ChartFileRules.Validate(list[0],Path.Combine(root,"nested"));}catch{blocked=true;}if(!blocked)return 82;File.AppendAllText(list[0].Path,"changed");blocked=false;try{ChartFileRules.Validate(list[0],root);}catch{blocked=true;}if(!blocked)return 83;var fresh=ChartFileRules.Read(root)[0];File.SetAttributes(fresh.Path,FileAttributes.ReadOnly);blocked=false;try{ChartFileRules.Validate(fresh,root);}catch{blocked=true;}File.SetAttributes(fresh.Path,FileAttributes.Normal);return blocked?0:84;}catch{return 89;}finally{if(Directory.Exists(root)){foreach(var f in Directory.GetFiles(root,"*",SearchOption.AllDirectories))File.SetAttributes(f,FileAttributes.Normal);Directory.Delete(root,true);}}}
}
}
